// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The stored document (download it with GET /patient-documents/{document_id}/download). */
export interface PatientDocumentUploadOut {
  document_id: number;
  patient_id: number;
  doc_type: "Photo" | "CNIC" | "PanelCard" | "Consent" | "ReferralLetter" | "DeathCertificate" | "AutopsyReport" | "PostMortemReport" | "MedicoLegalReport" | "LabReport" | "Imaging" | "DischargeSummary" | "Prescription" | "Other";
  title: string | null;
  content_type: "application/pdf" | "image/jpeg" | "image/png";
  size_bytes: number;
  /** Brought by the patient from another hospital, laboratory or clinic: show it labelled as an outside document, never as a result of this hospital */
  is_outside: boolean;
  /** The hospital, laboratory or clinic that issued an outside document */
  source_facility: string | null;
  /** The date written on the document (the test, the report, the visit) */
  document_date: string | null;
  uploaded_at: string;
}

