/** Upload a patient document (PDF/JPEG/PNG) — POST /api/v1/patients/{patient_id}/documents (who may call: holders of patient.document.upload). */
export function uploadDocumentPatientsDocuments(patient_id: number, body: FormData): Promise<PatientDocumentUploadOut> {
  return api<PatientDocumentUploadOut>("POST", `/patients/${patient_id}/documents`, body, { idempotent: true });
}

/** List patient documents — GET /api/v1/patients/{patient_id}/documents (who may call: holders of patient.document.view). */
export function listDocumentsPatients(patient_id: number): Promise<PatientDocumentOut[]> {
  return api<PatientDocumentOut[]>("GET", `/patients/${patient_id}/documents`, undefined);
}

/** Download a patient document — GET /api/v1/patient-documents/{document_id}/download (who may call: holders of patient.document.view). */
export function downloadDocumentPatientDocuments(document_id: number): Promise<unknown> {
  return api<unknown>("GET", `/patient-documents/${document_id}/download`, undefined);
}

/** Clear a discharge stage (in order) — POST /api/v1/admissions/{admission_id}/discharge/{stage}/clear (who may call: the permission of the stage: ipd.discharge.clear_pharmacy, clear_nursing, clear_billing or clear_cleaning). */
export function clearStage(admission_id: number, stage: "PharmacyClearance" | "NursingMARVerification" | "BillingSettlement" | "OpsCleaning", body: ClearIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/discharge/${stage}/clear`, body);
}

/** Finalize the running IPD bill (then collect payment) — POST /api/v1/admissions/{admission_id}/final-bill (who may call: holders of ipd.discharge.clear_billing). */
export function finalBill(admission_id: number, body: FinalBillIn): Promise<InvoiceDetailOut> {
  return api<InvoiceDetailOut>("POST", `/admissions/${admission_id}/final-bill`, body);
}

/** Admissions (default: all live ones; admissions desk queue) — GET /api/v1/admissions (who may call: holders of ipd.admission.view). */
export function listAdmissions(query?: { status?: string | null; ward_id?: number | null }): Promise<AdmissionOut[]> {
  return api<AdmissionOut[]>("GET", withQuery(`/admissions`, query), undefined);
}

/** Admissions desk: Allocate Bed — POST /api/v1/admissions/{admission_id}/allocate-bed (who may call: holders of ipd.admission.allocate). */
export function allocate(admission_id: number, body: AllocateIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/allocate-bed`, body);
}

/** Admissions manager: cross-ward overflow bed — POST /api/v1/admissions/{admission_id}/overflow-override (who may call: holders of ipd.admission.overflow). */
export function overflow(admission_id: number, body: OverflowIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/overflow-override`, body);
}

/** No bed: add to the ward waitlist — POST /api/v1/admissions/{admission_id}/waitlist (who may call: holders of ipd.waitlist.manage or ipd.admission.request). */
export function waitlist(admission_id: number, body: WaitlistIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/waitlist`, body);
}

/** Ward waitlist — GET /api/v1/wards/{ward_id}/waitlist (who may call: holders of ipd.admission.view). */
export function wardWaitlist(ward_id: number): Promise<WaitlistEntryOut[]> {
  return api<WaitlistEntryOut[]>("GET", `/wards/${ward_id}/waitlist`, undefined);
}

/** Patient arrived at the bed (Admitted, bed Occupied) — POST /api/v1/admissions/{admission_id}/admit (who may call: holders of ipd.admission.allocate or ipd.flowsheet.record). */
export function admit(admission_id: number): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/admit`, undefined, { idempotent: true });
}

/** Cancel an admission that will not happen (before the patient is admitted) — POST /api/v1/admissions/{admission_id}/cancel (who may call: holders of ipd.admission.allocate or ipd.admission.request). */
export function cancelAdmission(admission_id: number, body: AdmissionCancelIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/cancel`, body);
}

/** Confirm how a Code Red admission is paid (ends its billing deferral) — POST /api/v1/admissions/{admission_id}/confirm-billing (who may call: holders of ipd.admission.allocate or ipd.discharge.clear_billing). */
export function confirmBilling(admission_id: number, body: BillingConfirmIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/confirm-billing`, body);
}
